                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 50;

    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private int _messagesSkip;
    private bool _hasMoreMessages;
    private bool _isThreadOpen;
    private int? _activeThreadRootId;
    private Message? _threadRootMessage;
    private MessageArea? _messageArea;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _selectedChannelId = channelId;
        _messagesSkip = 0;
        _threadSummaries = [];
        CloseThreadInternal();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count == PageSize;
        _messagesSkip = messages.Count;

        await ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messagesSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messagesSkip += older.Count;
        }

        _hasMoreMessages = older.Count == PageSize;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
        _messagesSkip++;
        _messageArea?.ScrollToBottom();
    }

    private async Task OpenThread(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);

        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();

        _threadSummaries[rootMessageId] = new ThreadSummary(
            rootMessageId,
            _threadReplies.Count,
            _threadReplies.Count > 0 ? _threadReplies[^1].SentAt : DateTime.Now);

        _isThreadOpen = true;
    }

    private void CloseThread() => CloseThreadInternal();

    private void CloseThreadInternal()
    {
        _isThreadOpen = false;
        _activeThreadRootId = null;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeThreadRootId is null || _selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            _selectedChannel.Id, content, _activeThreadRootId);
        _threadReplies.Add(reply);

        _threadSummaries[_activeThreadRootId.Value] = new ThreadSummary(
            _activeThreadRootId.Value,
            _threadReplies.Count,
            reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
    }
}

