@code {
    [Parameter, EditorRequired]
    public string ChannelName { get; set; } = "";

    [Parameter]
    public string ChannelDescription { get; set; } = "";

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public bool HasMoreMessages { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private ElementReference _sentinelRef;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<MessageArea>? _dotNetRef;
    private string _newMessageText = "";
    private bool _isLoadingMore;
    private bool _shouldScrollToBottom;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat/MessageArea.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
            _shouldScrollToBottom = true;
        }

        if (_jsModule is not null && HasMoreMessages && _dotNetRef is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("initScrollObserver",
                    _sentinelRef, _messageListRef, _dotNetRef);
            }
            catch (JSException)
            {
                // Sentinel element may not be in the DOM yet
            }
        }

        if (_shouldScrollToBottom && _jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
            _shouldScrollToBottom = false;
        }
    }

    [JSInvokable]
    public async Task LoadMoreMessages()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;
        StateHasChanged();

        double prevScrollHeight = 0;
        if (_jsModule is not null)
        {
            prevScrollHeight = await _jsModule.InvokeAsync<double>("getScrollHeight", _messageListRef);
        }

        await OnLoadMore.InvokeAsync();

        if (_jsModule is not null && prevScrollHeight > 0)
        {
            // Allow the DOM to update before restoring scroll position
            await Task.Yield();
            await _jsModule.InvokeVoidAsync("restoreScrollPosition", _messageListRef, prevScrollHeight);
        }

        _isLoadingMore = false;
        StateHasChanged();
    }

    public void ScrollToBottom() => _shouldScrollToBottom = true;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        var text = _newMessageText?.Trim();
        if (string.IsNullOrEmpty(text)) return;

        _newMessageText = "";
        _shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(text);
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("dispose");
            }
            catch (JSDisconnectedException)
            {
                // Circuit may already be gone
            }

            await _jsModule.DisposeAsync();
        }

        _dotNetRef?.Dispose();
    }
}

