.message-item {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

.message-author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #2c2f33;
}

.message-time {
    font-size: 0.75rem;
    color: #8e9297;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #36393f;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.3rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    background-color: #eef0f4;
    border: 1px solid #d3d6db;
    border-radius: 9999px;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: #dce0e8;
}

.thread-link {
    display: inline-block;
    margin-top: 0.3rem;
    font-size: 0.8rem;
    color: #5865f2;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.2rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    padding: 0.15rem;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    padding: 0.2rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    border-radius: 3px;
    color: #4f545c;
    white-space: nowrap;
}

.action-btn:hover {
    background-color: #f2f3f5;
    color: #2c2f33;
}

.emoji-picker {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    transform: translateY(-100%);
    display: flex;
    gap: 0.2rem;
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 0.3rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.3rem;
    border-radius: 4px;
    line-height: 1;
}

.emoji-option:hover {
    background-color: #f2f3f5;
}

